    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items.
    // We increase score (penalty) if post_residual is small but > 0.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive about filling bins.
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as progress increases.
    if bin_residual == bin_capacity {
        score += 10.0 + (progress * 40.0);
    }

    // Coupling with mean_residual: If this bin is significantly emptier than the average,
    // prioritize filling it to bring it closer to the mean (load balancing).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    if bin_residual > (mean_residual as u32) {
        score -= deviation * 0.5;
    }

    // If only one bin can fit this item, prioritize it strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

