pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize post_residual (Best Fit), so it stays as the primary component.
    let mut score = post_res;

    // Penalty for leaving a bin with a "fragmented" residual (too small for most items).
    // As the stream progresses, we become more aggressive about filling bins tightly.
    let fragmentation_penalty = (100.0 - post_res).powf(1.5) * (1.0 + progress);
    score += fragmentation_penalty;

    // Lookahead logic: If we know the next item, penalize leaving a bin that 
    // cannot accommodate that item if the current bin is nearly empty.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 150.0 * (1.0 - progress);
        }
    }

    // Heuristic for opening new bins:
    // If this is an empty bin (bin_residual == bin_capacity), calculate a threshold
    // based on the density of existing bins. We only open a new bin if the current
    // fitting options are poor (high post_residual).
    if bin_residual == bin_capacity {
        // High score for empty bin makes it less attractive unless existing bins are bad.
        // We modulate this by mean_residual; if mean_residual is low, we are packing well,
        // so we make it harder to open a new bin.
        score = 80.0 + (mean_residual * 2.0) + (progress * 50.0);
    } else {
        // If it's the last bin that can fit the item, give it a significant boost
        // to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common item sizes)
    // We penalize residuals in the range [1, 9] heavily as they are likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization (Harmonic coupling)
    // If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if the post_residual is a near-perfect fit for the next item
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. Balance bin utilization vs. opening new bins
    // If this is a new bin, penalize it based on how many bins are already open
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Favor bins that are already "well-filled" to consolidate space
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity adjustment
    // If this is the last fitting bin, slightly reward using it to prevent fragmenting
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Harmonic packing logic
    // Penalize residuals that are not multiples of common small divisors (e.g., 10, 20)
    // to keep the residual space "clean" for future items.
    let mod_val = post_residual % 10;
    score += mod_val as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict dead space avoidance: Penalize post_residual values that are likely to be unusable.
    // Gaps between 1 and 9 are extremely difficult to fill given item sizes start at 10.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // 2. Open bins pressure: If this is an existing bin, penalize the score based on the number of open bins.
    // This encourages filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 3. Lookahead coupling: If a second item is known, try to leave space for it if possible.
    // If post_residual is just slightly too small to fit the next item, it is a "bad" fit.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 150.0;
    }

    // 4. Fitting bin count awareness: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 5. New bin penalty: If this call represents a brand new bin, add a significant constant 
    // to force the algorithm to prefer existing bins unless the "Best Fit" is truly terrible.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0;
    }

    // 6. Mean residual balancing: Penalize placing items in bins that are significantly 
    // emptier than the current average to maintain a tighter packing density.
    if bin_residual < bin_capacity && (bin_residual as f64) > mean_residual {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot fit common small items (e.g., < 20)
    // We prioritize bins that leave very little space (Best Fit)
    // If the bin is new, we apply a high initial penalty to discourage opening new bins unless necessary
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // Harmonic Class Logic: 
    // We penalize post_residuals that are in the range (0, 20), as these are often 'wasted' 
    // unless the next item is small enough to fill them.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead Coupling:
    // If we have a next item, we reward bins that leave exactly enough room for it 
    // or leave enough room to maintain a healthy mean_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff < 10 {
            score -= 15.0; // Strong reward for perfect lookahead fit
        }
    }

    // Global Density Control:
    // As the stream progresses, prioritize filling existing bins more aggressively
    // to reduce the count of open bins (open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * 2.0 * progress;

    // Penalize bins that deviate significantly from the current mean_residual 
    // to keep the bin landscape uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Hard Constraint Logic:
    // If this is the only bin that can fit the item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We heavily penalize large post_residuals to keep bins packed tightly.
    let mut score = post_res * post_res;

    // Lookahead interaction: If the next item is large, we want to leave
    // a residual that is either near 0 or large enough to accommodate the next item.
    if next_item_size > 0 {
        let diff = (post_res - next_item_size as f64).abs();
        // If post_residual is just slightly too small for the next item, penalize heavily.
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res).powi(3);
        } else {
            // Reward residuals that perfectly match or slightly exceed the next item.
            score -= (100.0 - diff) * 0.5;
        }
    }

    // Dynamic density pressure: As the stream progresses, prioritize closing bins
    // by penalizing the creation of new bins when fitting_bins_count > 0.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to progress.
        // We make it harder to open a new bin as we approach the end of the stream.
        score += 500.0 * (1.0 + progress);
    } else {
        // Reward bins that bring the mean residual closer to a target packing efficiency (e.g., 5-10% waste).
        let efficiency_penalty = (post_res - 8.0).powi(2);
        score += efficiency_penalty * 0.1;
    }

    // If this is the only bin that can fit the item, give it a significant priority boost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor [0.0, 1.0]
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle: smaller post_residual is better)
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (e.g., residual < 10)
    // Small residuals are hard to fill; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead optimization
    // If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global state awareness
    // Discourage opening too many bins early in the stream unless necessary.
    // If we are late in the game, prioritize closing bins (lower score for smaller post_residual).
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0 * (1.0 - progress);
    }

    // 4. Fitting bin pressure
    // If this is the only bin that can fit the item (fitting_bins_count == 1),
    // heavily incentivize using it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. New Bin Logic
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the mean_residual of existing bins is already very small (tight),
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open
        } else {
            // Otherwise, make opening a new bin expensive to favor existing bins.
            score = 80.0 - (mean_residual * 0.5);
        }
    }

    score
}
